export const isMatch = <TMatch, TPath extends string>(
  match: TMatch,
  path: Constrain<TPath, IsMatch<TMatch, TPath>['path']>,
): match is IsMatch<TMatch, TPath>['result'] => {
  const parts = (path as string).split('.')
  let part
  let i = 0
  let value: any = match

  while ((part = parts[i++]) != null && value != null) {
    value = value[part]
  }

  return value != null
}
